design.css:
.section-view-folder-pane .folder-row { border-radius: 0; }
.note-status-bar {
  gap: 12px;
  padding: 3px 12px;
  border: 1px solid #741b1b;
  border-top-color: #a34336;
  border-radius: 3px;
  color: #f4e5d0;
  background: linear-gradient(180deg, #381313, #180b0b);
  box-shadow: inset 0 0 0 2px #180b0b, 0 3px 12px #00000040;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 600;
  font-variant-numeric: lining-nums tabular-nums;
  letter-spacing: 0.025em;
}
.ProseMirror::selection, .ProseMirror *::selection, .note-title-input::selection, .raw-markdown-input::selection {
  background: #b43a3a;
  color: #ffffff;
}
